import {
  readStdin
} from "./packager-tool-79gws1zn.js";
import {
  getFileSystem
} from "./packager-tool-0v3s8r01.js";

// ../maestro-sdk/src/json-input.ts
async function readJsonFile(filePath) {
  const fs = getFileSystem();
  const resolved = fs.path.resolve(filePath);
  if (!await fs.exists(resolved)) {
    throw new Error(`File not found: ${resolved}`);
  }
  const content = await fs.readFile(resolved, "utf-8");
  try {
    return JSON.parse(content);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`Invalid JSON in '${resolved}': ${message}`);
  }
}
async function parseJsonInputOrFile(inputSource) {
  if (inputSource.startsWith("@")) {
    const filePath = inputSource.slice(1);
    try {
      return await readJsonFile(filePath);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      throw new Error(`Failed to read input file '${filePath}': ${message}`);
    }
  }
  try {
    return JSON.parse(inputSource);
  } catch {
    throw new Error(`Failed to parse inputs as JSON: ${inputSource}`);
  }
}
async function resolveJsonInput(opts) {
  if (opts.inline !== undefined && opts.inline !== "") {
    return parseJsonInputOrFile(opts.inline);
  }
  if (opts.allowStdin) {
    const stdinData = await readStdin();
    if (stdinData) {
      return parseJsonInputOrFile(stdinData);
    }
  }
  return;
}

export { readJsonFile, parseJsonInputOrFile, resolveJsonInput };

